program='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # The horizontal color words are the multi-cell runs on the outer rows.
    words = []
    word_cells = set()
    for r in (0, h - 1):
        c = 0
        while c < w:
            if grid[r][c] == 0:
                c += 1
                continue
            start = c
            while c < w and grid[r][c] != 0:
                c += 1
            if c - start >= 2:
                word = grid[r][start:c]
                words.append(word)
                for x in range(start, c):
                    word_cells.add((r, x))
    # A marker copies its source word, with its own color aligned to its cell.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in word_cells:
                continue
            for word in words:
                if color in word:
                    k = word.index(color)
                    left = c - k
                    for j, v in enumerate(word):
                        x = left + j
                        if 0 <= x < w:
                            out[r][x] = v
                    break
    return out
'''
